// Package nativefeedback is an opt-in development bridge for the trusted main window.
package nativefeedback

type Config struct {
	CompanionURL string
}

//go:build !dev || !wailsfeedback || production

package nativefeedback

import "github.com/wailsapp/wails/v3/pkg/application"

// No transport or bound Service is compiled into an ordinary or production build.
type Bridge struct{}

func Start(Config) (*Bridge, error) { return nil, nil }

func Services(_ *Bridge, existing []application.Service) []application.Service { return existing }

func Attach(*Bridge, application.Window) {}

func Stop(*Bridge) {}

func InstanceID(_ *Bridge, original string) string { return original }

//go:build !dev || !wailsfeedback || production

package nativefeedback

import "testing"

func TestDisabledRegardlessOfRuntimeAndConfig(t *testing.T) {
	t.Setenv("WAILS_FEEDBACK", "1")
	bridge, err := Start(Config{CompanionURL: "invalid"})
	if bridge != nil || err != nil {
		t.Fatal("ordinary or production build enabled feedback")
	}
	if got := Services(bridge, nil); got != nil {
		t.Fatal("disabled bridge registered service")
	}
	Attach(bridge, nil)
	Stop(bridge)
	if got := InstanceID(bridge, "original"); got != "original" {
		t.Fatal("release identity changed")
	}
