import { lazy, Suspense, useEffect, useState } from "react";
import { Call } from "@wailsio/runtime";
import { endpointFrom } from "./connection.mjs";
// Agentation loads only after exact-main-window authorization from Go.
const Overlay = lazy(() => import("./FeedbackOverlay"));

export default function FeedbackGate() {
  const [endpoint, setEndpoint] = useState<string>();
  const [failed, setFailed] = useState(false);
  const [attempt, setAttempt] = useState(0);
  useEffect(() => {
    const controller = new AbortController();
    const configuration = Call.ByName("github.com/MylesMCook/burf/app/native" + "/internal/nativefeedback.Service.Configuration");
    const timeout = setTimeout(() => { configuration.cancel(); controller.abort(); setFailed(true); }, 15000);
    setFailed(false);
    void (async () => {
      const next = endpointFrom(await configuration);
      const health = await fetch(`${next}/health`, { signal: controller.signal });
      if (!health.ok) throw new Error("Feedback companion is unavailable.");
      if (!controller.signal.aborted) setEndpoint(next);
    })().catch(() => { if (!controller.signal.aborted) setFailed(true); }).finally(() => clearTimeout(timeout));
    return () => { clearTimeout(timeout); configuration.cancel(); controller.abort(); };
  }, [attempt]);
  if (endpoint) return <Suspense fallback={null}><Overlay endpoint={endpoint} /></Suspense>;
  if (failed) return <button type="button" onClick={() => setAttempt(value => value + 1)}>Retry feedback connection</button>;
  return null;
}

import { Agentation } from "agentation";

export default function FeedbackOverlay({ endpoint }: { endpoint: string }) {
  return <Agentation appName={"burf"} endpoint={endpoint} />;
}

import { lazy, Suspense } from "react";
import { trustedWindow } from "./connection.mjs";

declare const __WAILS_FEEDBACK__: boolean;

// The marker is emitted by the application's existing trusted asset middleware.
// Importing the Wails runtime alone is not evidence of a trusted native window.
const Overlay = __WAILS_FEEDBACK__ ? lazy(() => import("./FeedbackGate")) : null;

export function NativeFeedback() {
  if (!__WAILS_FEEDBACK__ || !Overlay) return null;
  const trusted = trustedWindow(typeof window === "undefined" ? undefined : window, "__BURF_WAILS__");
  if (!trusted) return null;
  return <Suspense fallback={null}><Overlay /></Suspense>;
}

export function trustedWindow(scope, marker) {
  if (!scope || scope.top !== scope.self || !scope.location) return false;
  const location = scope.location;
  const port = location.port ?? (location.host?.match(/:(\d+)$/)?.[1] ?? "");
  const hostname = location.hostname ?? location.host?.replace(/:\d+$/, "");
  const validPort = port === "" || (/^\d+$/.test(port) && Number(port) >= 1024 && Number(port) <= 65535);
  const nativeOrigin = validPort && ((location.protocol === "http:" && hostname === "wails.localhost") || (location.protocol === "wails:" && hostname === "localhost"));
  return nativeOrigin && (marker === null || scope[marker] === true);
}

export function endpointFrom(value) {
  if (!value || typeof value !== "object" || typeof value.endpoint !== "string") throw new Error("Feedback configuration is unavailable.");
  const url = new URL(value.endpoint);
  if (url.protocol !== "http:" || url.hostname !== "127.0.0.1" || !url.port || Number(url.port) < 1024 ||
      url.username || url.password || url.search || url.hash || !/^\/[a-f0-9]{32}$/.test(url.pathname)) throw new Error("Feedback endpoint is invalid.");
  return value.endpoint;
}

import type { ConfigEnv, UserConfigExport } from "vite";
export function feedbackEnabled(environment: Pick<ConfigEnv, "mode" | "command">, requested?: string): boolean;
export function withNativeFeedback(configuration: UserConfigExport, startupEntries?: string[]): UserConfigExport;

import { nativeStylexHMR } from "./stylex-hmr.mjs";
import { nativeStartup } from "./startup.mjs";
// Wrap, rather than replace, the application's Vite configuration.
export function feedbackEnabled(environment, requested = process.env.WAILS_FEEDBACK) {
  return requested === "1" && environment.command === "serve" && environment.mode === "feedback";
}

export function withNativeFeedback(configuration, startupEntries = ["/src/main.tsx"]) {
  return async (environment) => {
    const existing = await (typeof configuration === "function" ? configuration(environment) : configuration);
    const enabled = feedbackEnabled(environment);
    if (existing.define && Object.hasOwn(existing.define, "__WAILS_FEEDBACK__")) {
      throw new Error("__WAILS_FEEDBACK__ is reserved for native feedback setup.");
    }
    return {
      ...existing,
      define: { ...existing.define, __WAILS_FEEDBACK__: JSON.stringify(enabled) },
      // Native Windows uses wails.localhost for assets; connect HMR directly
      // to the owned loopback server instead of waiting on that synthetic host.
      ...(enabled && existing.server?.hmr === undefined ? { server: { ...existing.server, hmr: { protocol: "ws", host: "127.0.0.1" } } } : {}),
      plugins: [
        ...(existing.plugins ?? []),
        ...(enabled ? [nativeStylexHMR(), nativeStartup(startupEntries), {
          name: "wails-native-feedback-development-marker",
          transformIndexHtml() {
            return [{ tag: "meta", attrs: { name: "wails-native-feedback", content: "development" }, injectTo: "head" }];
          },
        }] : []),
      ],
    };
  };
}

// Prepare source without executing it or reading the application's UI state.
export const readinessPath = "/__wails-feedback-ready";
export function nativeStartup(entries) {
  return {
    name: "wails-native-feedback-startup",
    configureServer(server) {
      let started = false, ready = false, failed = false;
      const environment = server.environments?.client ?? server;
      if (typeof environment.transformRequest !== "function" || typeof environment.waitForRequestsIdle !== "function" || !server.httpServer) {
        throw new Error("Native feedback needs a standalone Vite server with module readiness support.");
      }
      const prepare = () => {
        if (started) return;
        started = true;
        void (async () => {
          await Promise.all(entries.map(async entry => {
            if (!await environment.transformRequest(entry)) throw new Error("Missing startup module " + entry);
          }));
          await environment.waitForRequestsIdle();
          ready = true;
        })().catch(error => {
          failed = true;
          server.config.logger.error("Native feedback frontend preparation failed: " + error.message);
        });
      };
      server.middlewares.use((req, res, next) => {
        const path = (req.url ?? "").split("?")[0];
        if (req.method === "GET" && path === readinessPath) {
          res.setHeader("Cache-Control", "no-store");
          res.writeHead(ready ? 204 : failed ? 500 : 503);
          res.end();
          return;
        }
        // Let Vite process HTML normally: its initial optimizer scan needs it.
        if (req.method === "GET" && ["/", "/index.html"].includes(path)) prepare();
        next();
      });
    },
  };
}

// Wails' intercepted asset responses can be slow during cold module loading.
// StyleX's async custom-event callback otherwise blocks Vite's serial HMR queue.
export function nativeStylexHMR() {
  return {
    name: "wails-native-feedback-stylex-hmr",
    enforce: "post",
    transform(code, id) {
      if (!id.includes("virtual:stylex:runtime")) return null;
      const hook = "import.meta.hot.on('stylex:css-update', update);";
      const initial = "\nupdate();";
      const delayed = "setTimeout(update, AFTER_UPDATE_DELAY)";
      const fetch = "const r = await fetch(DEV_CSS_PATH + '?t=' + t, {cache: 'no-store'});\n  return r.text();";
      const result = "const css = await fetchCSS();";
      const dispose = "import.meta.hot.dispose(() => {";
      for (const expected of [hook, initial, delayed, fetch, result, dispose]) {
        if (code.split(expected).length !== 2) throw new Error("Unsupported StyleX development runtime; native feedback requires the reviewed full runtime shape.");
      }
      const worker = `
let nativeCSSDirty = false;
let nativeCSSRunning = false;
let nativeCSSDisposed = false;
let nativeCSSController;
function requestNativeCSSUpdate() {
  if (nativeCSSDisposed) return;
  nativeCSSDirty = true;
  if (nativeCSSRunning) return;
  nativeCSSRunning = true;
  void (async () => {
    try {
      while (nativeCSSDirty && !nativeCSSDisposed) {
        nativeCSSDirty = false;
        await update();
      }
    } finally { nativeCSSRunning = false; }
  })();
}
`;
      return {
        code: worker + code
          .replace(fetch, `const controller = new AbortController();
  nativeCSSController = controller;
  const timeout = setTimeout(() => controller.abort(), 5000);
  try {
    const r = await fetch(DEV_CSS_PATH + '?t=' + t, {cache: 'no-store', signal: controller.signal});
    return await r.text();
  } finally {
    clearTimeout(timeout);
    if (nativeCSSController === controller) nativeCSSController = undefined;
  }`)
          .replace(result, result + "\n    if (nativeCSSDisposed) return;")
          .replace(initial, "\nrequestNativeCSSUpdate();")
          .replace(hook, "import.meta.hot.on('stylex:css-update', requestNativeCSSUpdate);")
          .replace(delayed, "setTimeout(requestNativeCSSUpdate, AFTER_UPDATE_DELAY)")
          .replace(dispose, dispose + "\n    nativeCSSDisposed = true; nativeCSSDirty = false; nativeCSSController?.abort();"),
        map: null,
      };
    },
  };
}

import { createHash } from "node:crypto";
import { createRequire } from "node:module";
import { mkdir, readFile, writeFile } from "node:fs/promises";
import { dirname, join } from "node:path";

export async function prepareCompanion(frontend, state) {
  const require = createRequire(join(frontend, "package.json"));
  const entry = require.resolve("agentation-mcp");
  const packageRoot = dirname(dirname(entry));
  const metadata = JSON.parse(await readFile(join(packageRoot, "package.json"), "utf8"));
  if (metadata.version !== "1.3.2") throw new Error("The companion adapter requires agentation-mcp 1.3.2.");
  const source = await readFile(join(packageRoot, "dist/cli.js"), "utf8");
  const expected = "5ab7f2ed13dc966d7265a0a6815a0757e673a9615dd6966dfaac7bd8a2345612";
  if (createHash("sha256").update(source).digest("hex") !== expected) throw new Error("Agentation CLI bytes changed; review its local-store adapter first.");
  const original = 'const dataDir = (0, import_path.join)((0, import_os.homedir)(), ".agentation");';
  if (source.split(original).length !== 2) throw new Error("Unknown Agentation data-directory implementation.");
  const replacement = 'const dataDir = process.env.AGENTATION_DATA_DIR; if (!dataDir) throw new Error("Private feedback data directory is required");';
  // Use the original CLI's module resolution, including pnpm's transitive layout.
  const adapted = source.replace(original, replacement).replace('\n"use strict";', `\n"use strict";\nconst {createRequire: feedbackRequire} = require("node:module");\nrequire = feedbackRequire(${JSON.stringify(join(packageRoot, "dist/cli.js"))});`);
  await mkdir(state, { recursive: true, mode: 0o700 });
  const output = join(state, "agentation-local.cjs");
  await writeFile(output, adapted, { mode: 0o600 });
  await writeFile(join(state, "AGENTATION-LICENSE.txt"), await readFile(join(packageRoot, "LICENSE")), { mode: 0o600 });
  return output;
}

